def solve(data):
    packages = data.get('packages', {})
    names = sorted(packages)
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    features = set(data.get('features', []))
    best_vector = None
    best_versions = None

    required = {
        name: [(bounds[0], bounds[1])]
        for name, bounds in data.get('roots', {}).items()
    }

    def valid_version(name, row, constraints):
        version = row['version']
        if version in blocked.get(name, []):
            return False
        if name in pins and version != pins[name]:
            return False
        return all(low <= version <= high for low, high in constraints)

    def search(required, chosen, edges):
        nonlocal best_vector, best_versions

        for name, version in chosen.items():
            if not all(low <= version <= high
                       for low, high in required.get(name, [])):
                return

        unresolved = sorted(name for name in required if name not in chosen)
        if not unresolved:
            if not acyclic(edges):
                return
            vector = tuple(chosen.get(name, -1) for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = dict(chosen)
            return

        name = unresolved[0]
        rows = packages.get(name, [])
        candidates = [row for row in rows
                      if valid_version(name, row, required[name])]
        for row in candidates:
            version = row['version']
            next_chosen = dict(chosen)
            next_chosen[name] = version
            next_required = {key: list(value) for key, value in required.items()}
            next_edges = {key: list(value) for key, value in edges.items()}
