                if feature and feature not in features:
                    continue
                child = dep['name']
                next_required.setdefault(child, []).append((dep['min'], dep['max']))
                next_edges[name].append(child)

            search(next_required, next_chosen, next_edges)

    search(required, {}, {})
    if best_versions is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best_versions}
